tracks1, tracks2, tracks3, tracks4, turret, guns, wheels1, wheels2 = piece('tracks1', 'tracks2', 'tracks3', 'tracks4', 'turret', 'guns', 'wheels1', 'wheels2')
wheels3, wheels4, wheels5, wheels6, base, aim, flare1, flare2 = piece('wheels3', 'wheels4', 'wheels5', 'wheels6', 'base', 'aim', 'flare1', 'flare2')
barrel1, barrel2, a1, a2, neck = piece('barrel1', 'barrel2', 'a1', 'a2', 'neck')

include "smokeunit.lua"

local rad = math.rad
local COB2RAD = math.pi / 32768
local SIG_AIM = 1
local s0 = 0
local moving = 0
local gun_index = 0

local function Blow(list, flags)
	for _, p in ipairs(list) do Explode(p, flags) end
end

local function TrackControl()
	while moving ~= 0 do
		s0 = s0 + 1
		if s0 == 2 then
			Hide(tracks1)
			Show(tracks2)
		elseif s0 == 3 then
			Hide(tracks2)
			Show(tracks3)
		elseif s0 == 4 then
			Hide(tracks3)
			Show(tracks4)
		else
			s0 = 1
			Hide(tracks4)
			Show(tracks1)
		end
		Sleep(50)
	end
end

local function RestoreAfterDelay()
	Sleep(3000)
	Turn(turret, y_axis, 0, rad(599.85))
	Turn(guns, x_axis, 0, rad(599.85))
end

function script.Create()
	Hide(tracks2)
	Hide(tracks3)
	Hide(tracks4)
	gun_index = 0
	moving = 0
	s0 = 1
	StartThread(SmokeUnit, {base})
end

function script.StartMoving()
	moving = 1
	StartThread(TrackControl)
	Spin(wheels1, x_axis, rad(359.91), rad(10))
	Spin(wheels2, x_axis, rad(359.91), rad(10))
	Spin(wheels3, x_axis, rad(359.91), rad(10))
	Spin(wheels4, x_axis, rad(539.87), rad(15))
	Spin(wheels5, x_axis, rad(539.87), rad(15))
	Spin(wheels6, x_axis, rad(539.87), rad(15))
end

function script.StopMoving()
	moving = 0
	StopSpin(wheels1, x_axis, rad(29.99))
	StopSpin(wheels2, x_axis, rad(29.99))
	StopSpin(wheels3, x_axis, rad(29.99))
	StopSpin(wheels4, x_axis, rad(44.99))
	StopSpin(wheels5, x_axis, rad(44.99))
	StopSpin(wheels6, x_axis, rad(44.99))
end

function script.SweetSpot()
	return turret
end

function script.AimFromWeapon(num)
	return aim
end

function script.QueryWeapon(num)
	local piecenum = -1
	if gun_index ~= 0 then
		piecenum = flare1
	else
		piecenum = flare2
	end
	return piecenum
end

function script.AimWeapon(num, heading, pitch)
	Signal(SIG_AIM)
	SetSignalMask(SIG_AIM)
	Turn(turret, y_axis, heading, math.rad(670))  -- TA 3.1c aim speed (was rad(599.85))
	Turn(guns, x_axis, -pitch, math.rad(670))  -- TA 3.1c aim speed (was rad(599.85))
	WaitForTurn(turret, y_axis)
	WaitForTurn(guns, x_axis)
	StartThread(RestoreAfterDelay)
	return true
end

function script.FireWeapon(num)
	gun_index = gun_index == 0 and 1 or 0
	if gun_index ~= 0 then
		Move(barrel1, z_axis, -30)
		Move(barrel1, z_axis, 0, 60)
	else
		Move(barrel2, z_axis, -30)
		Move(barrel2, z_axis, 0, 60)
	end
end

local function HitByWeapon(x, z)
	local anglex, anglez = 500 * z, 500 * x
	Turn(base, z_axis, -(anglez * COB2RAD), rad(104.97))
	Turn(base, x_axis, anglex * COB2RAD, rad(104.97))
	WaitForTurn(base, z_axis)
	WaitForTurn(base, x_axis)
	Turn(base, z_axis, 0, rad(29.99))
	Turn(base, x_axis, 0, rad(29.99))
end

function script.HitByWeapon(x, z)
	StartThread(HitByWeapon, x, z)
end

function script.RockUnit(x, z)
	local anglex, anglez = 500 * z, 500 * x
	Turn(base, x_axis, anglex * COB2RAD, rad(49.99))
	Turn(base, z_axis, -(anglez * COB2RAD), rad(49.99))
	WaitForTurn(base, z_axis)
	WaitForTurn(base, x_axis)
	Turn(base, z_axis, 0, rad(20))
	Turn(base, x_axis, 0, rad(20))
end

function script.Killed(recentDamage, maxHealth)
	local severity = recentDamage / maxHealth * 100
	local corpsetype = 0
	if severity < 25 then
		corpsetype = 1
		Blow({base, a1, a2, neck}, SFX.NONE)
		Explode(turret, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({barrel1, barrel2}, SFX.NONE)
	elseif severity < 50 then
		corpsetype = 2
		Blow({base, a1, a2, neck}, SFX.NONE)
		Explode(turret, SFX.FALL + SFX.NO_HEATCLOUD)
		Blow({barrel1, barrel2}, SFX.FALL)
	else
		corpsetype = 2
		Blow({base, a1, a2, neck}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		Explode(turret, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Blow({barrel1, barrel2}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	end
	return corpsetype
end
